/**
 * Runtime 单实例内严格递增的实时事件封装。
 *
 * `sequence` 只用于把事件与 [`crate::ObservedSnapshot`] 的水位对齐，不跨 Runtime 重启持久化。
 */
export type RuntimeEventEnvelope = { sequence: number, emitted_at_ms: number, event: RuntimeEvent, };

/**
 * 当前 Host 实例公开给客户端的传输能力，不包含地址、Token 或业务状态。
 */
export type RuntimeHostCapabilities = { protocol_version: number, runtime_version: string, max_command_bytes: number, max_attachment_bytes: number | null, sse: boolean, streaming_upload: boolean,
/**
 * Additive 产品能力；空列表表示 Host 尚未启用正式 Desktop 产品投影。
 */
features?: Array<RuntimeHostFeature>, };

/**
 * Host 可以逐项声明的产品能力；Desktop 只检查当前页面实际依赖的项目。
 */
export type RuntimeHostFeature = "event_envelopes" | "application_snapshot" | "session_view" | "child_task_view" | "conversation_paging" | "tool_detail" | "queue_control" | "approval_queue" | "session_management";

/**
 * Host 已完成 Runtime 恢复并可以接受已授权请求。
 */
export type RuntimeHostHealth = { status: RuntimeHostHealthStatus, };

/**
 * `/health` 的稳定就绪状态。
 */
export type RuntimeHostHealthStatus = "ready";

/**
 * Runtime 对外可见的生命周期状态。
 */
export type RuntimeLifecycle = "running" | "shutting_down" | "stopped";

/**
 * 查询历史会话标题和正文。
 */
export type SearchConversationHistoryRequest = {
/**
 * 发起搜索的 Session，用于解析 Session/Workspace 范围。
 */
session_id: SessionId, query: string, scope: ConversationHistoryScope,
/**
 * 产品层分页偏移；客户端不得解析为存储序号。
 */
offset: number, limit: number, };

/**
 * 一页历史搜索结果。
 */
export type SearchConversationHistoryResult = { items: Array<ConversationHistoryHit>, next_offset: number | null,
/**
 * 部分派生索引仍在重建时，已就绪结果仍可展示。
 */
partial: boolean, failed_owners: Array<ConversationOwner>, };

/**
 * Runtime 中一个会话的不透明标识。
 */
export type SessionId = string;

/**
 * Session 是否仍可接受业务变更。
 */
export type SessionLifecycle = "active" | "archived";

/**
 * Session 列表的生命周期过滤条件。
 */
export type SessionListFilter = "active" | "archived" | "all";

/**
 * 一个 Session 的稳定摘要。
 */
export type SessionSummary = {
/**
 * Session 的不透明标识。
 */
session_id: SessionId,
/**
 * 创建 Session 时确定的展示标题。
 */
title: string,
/**
 * Session 后续 Run 当前使用的用户模型 key。
 */
model_key: ModelKey,
/**
 * Session 当前是活动还是归档状态。
 */
lifecycle: SessionLifecycle,
/**
 * UI 当前选中的 Agent 变体；具体 Run 仍以提交 Input 携带的值为准。
 */
current_variant: AgentVariant,
/**
 * 后续 Run 捕获的当前审批模式。
 */
approval_mode: ApprovalMode,
/**
 * 创建 Session 时冻结的 Workspace 绑定；`None` 表示普通未绑定会话。
 */
workspace_id?: WorkspaceId | null,
/**
 * 当前活动 Run；Session 空闲时为 `None`。
 */
active_run_id: RunId | null,
/**
 * 规范 Conversation 中已经完整提交的消息数量。
 */
message_count: number,
/**
 * 尚未进入规范 Conversation 的持久化输入数量。
 */
queued_input_count: number,
/**
 * 重启恢复后队列是否等待用户显式继续。
 */
resume_required: boolean,
/**
 * 老记录无法可靠恢复时保持为空。
 */
created_at_ms: number | null,
/**
 * 最近一次 Run 可靠终结的时间；尚无 Run 时等于创建时间。
 * 标题、固定状态、模式等元数据变更不得推进该时间。
 */
updated_at_ms: number | null, archived_at_ms: number | null, is_pinned: boolean, title_origin: SessionTitleOrigin, pending_approval_count: number, active_child_count: number, active_run_status: RunStatus | null, };

/**
 * Session 标题的来源，用于决定自动标题是否仍可被 Runtime 更新。
 */
export type SessionTitleOrigin = "generated" | "user";

/**
 * 只属于主会话、不聚合子任务的用量投影。
 */
export type SessionUsageSnapshot = { accumulated: UsageTotals | null, previous_turn: UsageTotals | null, context: ContextUsageSnapshot | null, };

/**
 * 主会话页面读取所需的组合投影。
 */
export type SessionViewSnapshot = { session: SessionSummary, active_run: RunSnapshot | null, queue: QueueSnapshot, approvals: ApprovalQueueSnapshot, attachments: Array<AttachmentSummary>, file_references: Array<ConversationFileReference>, runs: Array<RunSnapshot>, usage: SessionUsageSnapshot, child_tasks: Array<ChildTaskTreeItemSnapshot>, conversation: ConversationPage, };

export type SetDefaultModelRequest = { model_key: ModelKey, expected_revision: string, };

/**
 * 保存或清除一条 Assistant Message 的本地反馈。
 */
export type SetMessageFeedbackRequest = { session_id: SessionId, message_id: MessageId, feedback: MessageFeedback | null, };

export type SetMessageFeedbackResult = { message_id: MessageId, feedback: MessageFeedback | null, };

export type SetPersonaRequest = { expected_revision: number, enabled: boolean, content: string, };

export type SetPersonaResult = { applied: boolean, persona: PersonaSnapshot, };

/**
 * 更新 Session 后续 Run 捕获的审批模式。
 */
export type SetSessionApprovalModeRequest = { session_id: SessionId, approval_mode: ApprovalMode, };

export type SetSessionApprovalModeResult = { session: SessionSummary, };

/**
 * 切换 Session 后续 Run 使用的模型 key。
 */
export type SetSessionModelRequest = { session_id: SessionId, model_key: ModelKey, };

export type SetSessionModelResult = { session: SessionSummary, };

/**
 * 显式设置 Session 的固定状态；重复提交相同目标值保持幂等。
 */
export type SetSessionPinnedRequest = { session_id: SessionId, is_pinned: boolean, };

export type SetSessionPinnedResult = { session: SessionSummary, };

/**
 * 只更新 Session 当前展示和下次提交默认使用的 Agent 变体。
 */
export type SetSessionVariantRequest = { session_id: SessionId, variant: AgentVariant, };

export type SetSessionVariantResult = { session: SessionSummary, };

/**
 * 请求受控关闭 Runtime。
 */
export type ShutdownRuntimeRequest = Record<symbol, never>;

/**
 * 受控关闭请求被接受后的结果。
 */
export type ShutdownRuntimeResult = {
/**
 * 接受请求后的 Runtime 生命周期。
 */
lifecycle: RuntimeLifecycle, };

/**
 * 可靠提交一条用户输入；同 Session 内可按 key 幂等重试。
 */
export type SubmitInputRequest = {
/**
 * 目标 Session。
 */
session_id: SessionId,
/**
 * 原样进入规范 UserMessage 的文本；Runtime 负责非空白校验。
 */
message: string,
/**
 * 本次输入实际使用的 Agent 变体；不能由 Session 展示状态代替。
 */
variant: AgentVariant,
/**
 * 按用户选择顺序引用的 Session Attachment。
 */
attachment_ids?: Array<AttachmentId>,
/**
 * 可选的不透明请求身份；重复 key 直接返回首次结果。
 */
idempotency_key?: IdempotencyKey | null, };

/**
 * 输入已持久化接受的结果。
 */
export type SubmitInputResult = { input_id: InputId, run: RunSnapshot, };

export type SystemContextSnapshot = { session_id: SessionId, session_created_at_ms: number | null, parts: Array<string>, };

/**
 * 一次完整模型请求由 Provider 最终确认的 token 用量。
 */
export type TokenUsageSnapshot = {
/**
 * 本次请求消耗的输入 token。
 */
input_tokens: number,
/**
 * 本次响应产生的输出 token。
 */
output_tokens: number,
/**
 * Provider 报告的总 token；不在应用层重新计算。
 */
total_tokens: number,
/**
 * 输入 token 中命中缓存的数量；Provider 未提供时为 `None`。
 */
cached_input_tokens: number | null, };

/**
 * Run 中一个工具调用的当前观察快照。
 */
export type ToolActivitySnapshot = {
/**
 * 工具调用的不透明标识。
 */
call_id: ToolCallId,
/**
 * 模型可见的工具名称。
 */
tool_name: string,
/**
 * 当前工具活动状态。
 */
status: ToolActivityStatus,
/**
 * 截至快照时观察到的标准输出；事件丢失时可能不完整。
 */
stdout: string,
/**
 * 截至快照时观察到的标准错误输出；事件丢失时可能不完整。
 */
stderr: string, };

/**
 * 工具调用在 Run 观察投影中的状态。
 */
export type ToolActivityStatus = "proposed" | "running" | "completed" | "failed";

export type ToolApprovalSubject = { "type": "general", tool_name: string, } | { "type": "delegation", tool_name: string, title: string, task_summary: string, } | { "type": "file", tool_name: string, operation: string, path: string, } | { "type": "shell", tool_name: string, command: string, working_directory: string, timeout_ms: number, process_mode: string, };

/**
 * 应用层工具调用的不透明标识。
 */
export type ToolCallId = string;

/**
 * 点击工具事件后按需读取的详情。
 */
export type ToolDetailSnapshot = { owner: ConversationOwner, message_id: MessageId, run_id: RunId | null, call_id: ToolCallId, tool_name: string, status: ToolActivityStatus, input: ToolInputSnapshot,
/**
 * 有界、格式化后的完整请求 JSON；用于详情代码块，不替代结构化输入投影。
 */
request_json: string | null, result_summary: string | null,
/**
 * 有界、格式化后的完整结果 JSON；纯文本结果保持为空。
 */
result_json: string | null,
/**
 * 仅 `recall_memory` 提供；引用已由 Runtime 校验并转换为安全导航目标。
 */
recall: RecallToolDetailSnapshot | null, stdout: string | null, stderr: string | null, error: RuntimeErrorInfo | null, files: Array<ToolFileReference>, output_truncated: boolean, historical_fields_missing: boolean, };

/**
 * 消息列表中的低干扰工具事件。
 */
export type ToolEventSnapshot = { call_id: ToolCallId, tool_name: string, status: ToolActivityStatus, summary: string | null,
/**
 * 经过脱敏和结构化的输入；实时事件不携带，以快照为准。
 */
input: ToolInputSnapshot, };

/**
 * 工具结果中可再次由 Runtime 解析的稳定文件引用。
 */
export type ToolFileReference = { resource_ref_id: ResourceRefId, origin: ToolFileResourceOrigin, display_name: string, display_path: string | null, size_bytes: number | null, media_type: string | null, state: ToolFileResourceState, };

/**
 * 工具结果中可引用的文件。
 */
export type ToolFileResourceOrigin = "workspace_file" | "session_private_file";

export type ToolFileResourceState = "available" | "unavailable";

/**
 * 工具详情中经过脱敏和结构化的输入。
 */
export type ToolInputSnapshot = { "type": "general", summary: string, } | { "type": "delegation", title: string, task_summary: string, } | { "type": "file", operation: string, path: string, } | { "type": "shell", command: string, working_directory: string, timeout_ms: number, process_mode: string, } | { "type": "unavailable" };

/**
 * 工具流式输出的应用层通道。
 */
export type ToolOutputChannel = "stdout" | "stderr";

export type UpdateModelRequest = { model: ModelConfigurationInput, expected_revision: string, set_default: boolean, };

export type UpdatePinnedMemoryRequest = { id: string, expected_revision: number, category: string, content: string, attributes: { [key in string]: MemoryAttributeValue }, };

/**
 * HTTP 流式上传完成后的稳定业务结果。
 */
export type UploadAttachmentResult = { attachment: AttachmentSummary, };

/**
 * Provider 已确认 token 的可缺省合计。
 */
export type UsageTotals = { input_tokens: number | null, output_tokens: number | null, total_tokens: number | null, cached_input_tokens: number | null, };

/**
 * 可靠提交的用户消息。
 */
export type UserMessageSnapshot = { message_id: MessageId,
/**
 * 历史记录无法恢复归属时保持为空。
 */
input_id: InputId | null, text: string, attachment_ids: Array<AttachmentId>, created_at_ms: number | null, };

/**
 * 显式验证一个已配置模型的基本连接与协议响应。
 */
export type ValidateModelConnectionRequest = {
/**
 * 已保存模型或尚未写入配置的表单 candidate。
 */
target: ModelConnectionTarget, };

/**
 * 指定模型的连接验证结果。
 */
export type ValidateModelConnectionResult = {
/**
 * 本次使用的用户 model key。
 */
model_key: ModelKey,
/**
 * 成功或结构化失败。
 */
outcome: ConnectionValidationOutcome, };

/**
 * Runtime 中一个 Workspace 的不透明标识。
 */
export type WorkspaceId = string;

/**
 * Workspace 是否仍可供新 Session 选择。
 */
export type WorkspaceLifecycle = "active" | "removed";

/**
 * 一个 Workspace 的稳定业务投影。
 */
export type WorkspaceSummary = {
/**
 * Runtime 分配的不透明 Workspace 标识。
 */
workspace_id: WorkspaceId,
/**
 * Host canonicalize 后保存的用户工作目录。
 */
user_directory: string,
/**
 * Runtime Home 中由 Host 管理的 Workspace 级 Agent 私有目录。
 */
agent_directory: string,
/**
 * Workspace 当前是否可供新 Session 选择。
 */
lifecycle: WorkspaceLifecycle, created_at_ms: number, updated_at_ms: number, removed_at_ms: number | null, };
